 static int n;static void Check(bool b){if(!b)throw new Exception("policy "+n);n++;}
 static void Main(){string profile=Path.Combine(Path.GetTempPath(),"sargon-policy-profile"),watch=Path.Combine(profile,"Downloads");long now=DateTime.UtcNow.Ticks;var w=new Witness{Kind="ENGINE",Path=Path.Combine(watch,"file.bin"),Size=1024};Func<bool> allowed=()=>MonitorSafety.CanAutoQuarantine(w,0,watch,profile,now,now);Check(allowed());w.Kind="HASH";Check(!allowed());w.Kind="TEST";Check(!allowed());w.Kind="ENGINE";w.Test=true;Check(!allowed());w.Test=false;w.Size=Core.MaxVault+1;Check(!allowed());w.Size=-1;Check(!allowed());w.Size=Core.MaxVault;Check(allowed());Check(!MonitorSafety.CanAutoQuarantine(w,1,watch,profile,now,now));Check(!MonitorSafety.CanAutoQuarantine(w,0,watch,profile,0,now));Check(!MonitorSafety.CanAutoQuarantine(w,0,watch,profile,now+1,now));Check(!MonitorSafety.CanAutoQuarantine(w,0,watch,profile,now-TimeSpan.FromHours(24).Ticks,now));w.Path=Path.Combine(watch,"sub","file.bin");Check(!allowed());w.Path=Path.Combine(profile,"Documents","file.bin");Check(!allowed());w.Path=Path.Combine(watch+"-outside","file.bin");Check(!allowed());Check(!MonitorSafety.IsPersonalFolder(profile,profile));Check(!MonitorSafety.IsPersonalFolder(Path.Combine(profile,"AppData"),profile));Check(MonitorSafety.IsPersonalFolder(Path.Combine(profile,"Documents","nested"),profile));Check(!MonitorSafety.IsPersonalFolder(watch,""));Check(!MonitorSafety.CanAutoQuarantine(null,0,watch,profile,now,now));Check(EngineSafety.EicarOnly(new LocalEngineVerdict{Found=true,Signatures=new[]{"Win.Test.EICAR_HDB-1"}}));Check(!EngineSafety.EicarOnly(new LocalEngineVerdict{Found=true,Signatures=new[]{"Win.Test.EICAR_HDB-1","Win.Trojan.Real"}}));Check(!EngineSafety.EicarOnly(new LocalEngineVerdict{Found=true,Signatures=new[]{"Other.EICAR.Fake"}}));Check(!EngineSafety.EicarOnly(new LocalEngineVerdict{Found=false,Signatures=new[]{"Win.Test.EICAR_HDB-1"}}));Check(!EngineSafety.EicarOnly(null));Check(!EngineSafety.IsEicarSignature(null));Check(!MonitorSafety.SafeWatchRoot(profile,profile,watch));Check(!MonitorSafety.SafeWatchRoot(watch,profile,watch));Check(MonitorSafety.SafeWatchRoot(watch,Path.Combine(profile,"AppData"),Path.Combine(profile,"Install")));Console.WriteLine("PASS: "+n+" automatic-quarantine policy checks; no native Windows file deletion performed.");}
